    + ## odb.h ##
    +@@ odb.h: struct odb_generate_pack_options {
    + 	/* Use offset deltas instead of reference deltas. */
    + 	unsigned ofs_delta:1;
    + 
    ++	/* Do not use reference deltas. */
    ++	unsigned no_ref_delta:1;
    ++
    + 	/* Include unasked-for annotated tags of packed objects. */
    + 	unsigned include_tag:1;
    + 
    +
    + ## odb/source-files.c ##
    +@@ odb/source-files.c: static int odb_source_files_generate_pack(struct odb_source *source UNUSED,
    + 		strvec_push(&cp->args, "--shallow");
    + 	if (opts->ofs_delta)
    + 		strvec_push(&cp->args, "--delta-base-offset");
    ++	if (opts->no_ref_delta)
    ++		strvec_push(&cp->args, "--no-ref-delta");
    + 	if (opts->include_tag)
    + 		strvec_push(&cp->args, "--include-tag");
    + 	if (opts->missing_allow_promisor)
    +
      ## send-pack.c ##
    +@@ send-pack.c: static int pack_objects(struct repository *r,
    + 
    + 	opts.thin = args->use_thin_pack;
    + 	opts.ofs_delta = args->use_ofs_delta;
    ++	opts.no_ref_delta = args->no_ref_delta;
    + 	if (args->progress)
    + 		opts.progress = ODB_GENERATE_PACK_PROGRESS_VERBOSE;
    + 	opts.shallow = is_repository_shallow(r);
     @@ send-pack.c: int send_pack(struct repository *r,
      	int need_pack_data = 0;
      	int allow_deleting_refs = 0;
    @@ send-pack.c: int send_pack(struct repository *r,
      		args->use_ofs_delta = 1;
     -	if (server_supports("side-band-64k"))
     -		use_sideband = 1;
    ++	if (server_supports("no-ref-delta"))
    ++		args->no_ref_delta = 1;
     +	use_sideband = use_sideband && server_supports("side-band-64k");
      	if (server_supports("quiet"))
      		quiet_supported = 1;
      	if (server_supports("agent"))
    +
    + ## send-pack.h ##
    +@@ send-pack.h: struct send_pack_args {
    + 		force_update:1,
    + 		use_thin_pack:1,
    + 		use_ofs_delta:1,
    ++		no_ref_delta:1,
